"use client";
import { useMemo, useState } from "react";import type { HistoryPoint } from "@/lib/types";
const windows=[{key:"24H",hours:24},{key:"7D",hours:168},{key:"30D",hours:720},{key:"90D",hours:2160}] as const;
export default function HistoryChart({points}:{points:HistoryPoint[]}){const newest=points.length?new Date(points[points.length-1].at).getTime():0;const availableHours=points.length>1?(newest-new Date(points[0].at).getTime())/3600000:0;const defaultKey=availableHours>=24?"24H":"7D";const [period,setPeriod]=useState(defaultKey);
const visible=useMemo(()=>{const w=windows.find(x=>x.key===period);if(!w||!newest)return points;const cutoff=newest-w.hours*3600000;return points.filter(p=>new Date(p.at).getTime()>=cutoff);},[points,period,newest]);
const vals=visible.filter(p=>p.playing!=null).map(p=>p.playing!);if(vals.length<2)return <div className="chart-empty"><strong>데이터 수집 중</strong><p>실제 Snapshot이 쌓이면 24시간부터 차례대로 그래프가 열립니다. 결측 구간은 0으로 채우지 않습니다.</p></div>;
const min=Math.min(...vals),max=Math.max(...vals),range=Math.max(1,max-min);const coords=visible.map((p,i)=>p.playing==null?null:{x:(i/Math.max(1,visible.length-1))*100,y:42-((p.playing-min)/range)*36});let path="";let open=false;coords.forEach(c=>{if(!c){open=false;return;}path+=`${open?"L":"M"}${c.x.toFixed(2)} ${c.y.toFixed(2)} `;open=true;});
return <div className="chart-card"><div className="chart-tabs" aria-label="차트 기간">{windows.map(w=><button key={w.key} disabled={availableHours<w.hours*.8} className={period===w.key?"active":""} onClick={()=>setPeriod(w.key)}>{w.key}{availableHours<w.hours*.8&&<span className="sr-only"> 데이터 수집 중</span>}</button>)}<button disabled>ALL<span className="sr-only"> 데이터 수집 중</span></button></div><svg className="history-chart" viewBox="0 0 100 48" role="img" aria-label={`플레이 인원 ${period} 변화 그래프`} preserveAspectRatio="none"><line x1="0" y1="42" x2="100" y2="42"/><line x1="0" y1="24" x2="100" y2="24"/><line x1="0" y1="6" x2="100" y2="6"/><path d={path.trim()}/></svg><div className="chart-range"><span>{min.toLocaleString("ko-KR")}</span><span>{max.toLocaleString("ko-KR")}</span></div><details className="accessible-data"><summary>차트 데이터 표로 보기</summary><div className="table-scroll"><table><thead><tr><th>시각</th><th>플레이 인원</th></tr></thead><tbody>{visible.map((p,i)=><tr key={i}><td>{new Date(p.at).toLocaleString("ko-KR")}</td><td>{p.playing==null?"결측":p.playing.toLocaleString("ko-KR")}</td></tr>)}</tbody></table></div></details></div>}
